    }
}
```

### Step 2: Write the Load Test Using TestNG

We'll write a TestNG test that simulates multiple users accessing the `UserService` simultaneously. We'll use the `@Test` annotation with the `threadPoolSize` attribute to run tests in parallel.

#### Step 2.1: Define the Test Method

The test method will simulate a user accessing the service and will be executed multiple times in parallel.

```java
import org.mockito.Mockito;
import org.testng.annotations.BeforeClass;
import org.testng.annotations.DataProvider;
import org.testng.annotations.Test;

public class UserServiceLoadTest {

    private UserRepository userRepository;
    private UserService userService;

    @BeforeClass
    public void setUp() {
        userRepository = Mockito.mock(UserRepository.class);
        userService = new UserService(userRepository);
    }

    @DataProvider(name = "userData")
    public Object[][] provideUserData() {
        return new Object[][] {
            {"123", "John Doe"},
            {"456", "Jane Smith"},
            {"789", "Alice Johnson"}
        };
    }

    @Test(dataProvider = "userData", threadPoolSize = 5, invocationCount = 10)
    public void testGetUserById(String userId, String expectedName) {
        // Arrange
        User mockUser = new User(userId, expectedName);
        Mockito.when(userRepository.getUserById(userId)).thenReturn(mockUser);

        // Act
