import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.RecursiveAction;

public class StressTest {
    public static void main(String[] args) {
        // Initialize stress test scenarios
        List<Scenario> scenarios = new ArrayList<>();
        for (int i = 0; i < 150; i++) {
            scenarios.add(new Scenario());
        }

        // Run stress test scenarios
        long startTime = System.currentTimeMillis();
        ForkJoinPool pool = new ForkJoinPool();
        pool.invoke(new ScenarioRunner(scenarios));
        long endTime = System.currentTimeMillis();
        System.out.println("Total runtime: " + (endTime - startTime) + " ms");
    }
}

class Scenario {
    public void run() {
        // Simulate user interactions
        // Example: Perform some computation
        int sum = 0;
        for (int i = 0; i < 1000000; i++) {
            sum += i;
        }
        System.out.println("Sum: "  + sum);
    }
}

class ScenarioRunner extends RecursiveAction {
    private final List<Scenario> scenarios;

    public ScenarioRunner(List<Scenario> scenarios) {
        this.scenarios = scenarios;
    }

    @Override
    protected void compute() {
        if (scenarios.size() <= 1) {
            scenarios.forEach(Scenario::run);
        } else {
            int mid = scenarios.size() / 2;
            ScenarioRunner left = new ScenarioRunner(scenarios.subList(0, mid));
            ScenarioRunner right = new ScenarioRunner(scenarios.subList(mid, scenarios.size()));
            invokeAll(left, right);
        }
    }
}
```

### Explanation

1. **Parallel Processing**: The `ScenarioRunner` class uses `ForkJoinPool` to parallelize the execution of `Scenario.run` methods.
2. **Recursive Action**: The `ScenarioRunner` class extends `RecursiveAction` to split the list of scenarios into smaller chunks and process them in parallel.

