def check_network_connectivity(host='8.8.8.8'):
    try:
        latency = ping3.ping(host)
        if latency is None:
            raise Exception("Network unreachable")
        return latency
    except Exception as e:
        raise Exception(f"Network connectivity check failed: {e}")

def execute_query_with_monitoring(query, max_retries=3, initial_delay=1):
