import requests

class BugTracker:
    def __init__(self, jira_url, api_token, email):
        self.jira_url = jira_url
        self.api_token = api_token
        self.email = email
        self.auth = (email, api_token)
        self.headers = {
            'Content-Type': 'application/json',
            'Accept': 'application/json'
        }

    def add_bug(self, bug):
        data = {
            "fields": {
                "project": {"key": bug['project']},
                "summary": bug['summary'],
                "description": bug['description'],
                "issuetype": {"name": "Bug"},
                "priority": {"name": bug['priority']},
                "labels": ["critical"] if bug['severity'] == 'critical' else []
            }
        }
        response = requests.post(
            f"{self.jira_url}/rest/api/3/issue",
            json=data,
            headers=self.headers,
            auth=self.auth
        )
        if response.status_code == 201:
            print(f"Bug added: {response.json()['key']}")
        else:
            print(f"Failed to add bug: {response.content}")

    def get_open_bugs(self):
        params = {
            "jql": "status = open",
            "fields": ["key", "summary", "status", "priority", "labels"]
        }
        response = requests.get(
            f"{self.jira_url}/rest/api/3/search",
            params=params,
            headers=self.headers,
            auth=self.auth
        )
        if response.status_code == 200:
            return response.json()['issues']
        else:
            print(f"Failed to retrieve open bugs: {response.content}")
            return []

    def get_critical_bugs(self):
        params = {
            "jql": "labels = critical",
            "fields": ["key", "summary", "status", "priority", "labels"]
        }
        response = requests.get(
            f"{self.jira_url}/rest/api/3/search",
            params=params,
            headers=self.headers,
            auth=self.auth
        )
        if response.status_code == 200:
            return response.json()['issues']
        else:
            print(f"Failed to retrieve critical bugs: {response.content}")
            return []

    def get_open_critical_bugs(self):
        params = {
            "jql": "status = open AND labels = critical",
            "fields": ["key", "summary", "status", "priority", "labels"]
        }
        response = requests.get(
            f"{self.jira_url}/rest/api/3/search",
            params=params,
            headers=self.headers,
            auth=self.auth
        )
        if response.status_code == 200:
            return response.json()['issues']
        else:
            print(f"Failed to retrieve open critical bugs: {response.content}")
            return []

    def prioritize_critical_bugs(self):
        open_critical_bugs = self.get_open_critical_bugs()
        for bug in open_critical_bugs:
            print(f"Prioritizing critical bug: {bug['key']}")
            # Optionally, update the priority or add a label to indicate high priority
            self.update_bug_priority(bug['key'], 'Highest')

    def update_bug_priority(self, issue_key, new_priority):
        data = {
            "fields": {
                "priority": {"name": new_priority}
            }
        }
        response = requests.put(
            f"{self.jira_url}/rest/api/3/issue/{issue_key}",
            json=data,
            headers=self.headers,
            auth=self.auth
        )
        if response.status_code == 204:
            print(f"Bug priority updated to {new_priority}")
        else:
            print(f"Failed to update bug priority: {response.content}")

    def close_bug(self, issue_key):
        transition_id = self._get_transition_id(issue_key, 'Close')
        data = {
            "transition": {
                "id": transition_id
            }
        }
        response = requests.post(
            f"{self.jira_url}/rest/api/3/issue/{issue_key}/transitions",
            json=data,
            headers=self.headers,
            auth=self.auth
        )
        if response.status_code == 204:
            print(f"Bug closed: {issue_key}")
        else:
            print(f"Failed to close bug: {response.content}")

    def _get_transition_id(self, issue_key, new_status):
        response = requests.get(
            f"{self.jira_url}/rest/api/3/issue/{issue_key}/transitions",
            headers=self.headers,
            auth=self.auth
        )
        if response.status_code == 200:
            transitions = response.json()['transitions']
            for transition in transitions:
                if transition['name'].lower() == new_status.lower():
                    return transition['id']
        raise ValueError(f"Transition to {new_status} not found")

    def report_progress(self):
        open_bugs = len(self.get_open_bugs())
        critical_bugs = len(self.get_critical_bugs())
        open_critical_bugs = len(self.get_open_critical_bugs())
        print(f"Open bugs: {open_bugs}")
        print(f"Critical bugs: {critical_bugs}")
        print(f"Open critical bugs: {open_critical_bugs}")

